-- ── Database & user setup ─────────────────────────────────────────────────────

CREATE USER keycloak WITH PASSWORD 'keycloak';
CREATE DATABASE keycloak OWNER keycloak;
CREATE DATABASE productdb;
CREATE DATABASE orderdb;
CREATE DATABASE userdb;
CREATE DATABASE notificationdb;
CREATE DATABASE paymentdb;

-- ── productdb ─────────────────────────────────────────────────────────────────

\c productdb

CREATE TABLE IF NOT EXISTS products (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name            VARCHAR(255) NOT NULL,
    description     TEXT,
    price           NUMERIC(10,2) NOT NULL,
    category        VARCHAR(255) NOT NULL,
    brand           VARCHAR(255),
    rating          FLOAT8,
    review_count    INTEGER,
    stock           INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS product_images (
    product_id  BIGINT  NOT NULL REFERENCES products(id),
    image_order INTEGER NOT NULL,
    image_url   VARCHAR(255)
);



-- Advance the identity sequence past the seeded IDs
SELECT setval(pg_get_serial_sequence('products', 'id'), 6918363302);

-- ── userdb ────────────────────────────────────────────────────────────────────

\c userdb

CREATE TABLE IF NOT EXISTS users (
    id                  VARCHAR(255) PRIMARY KEY,
    username            VARCHAR(255) NOT NULL UNIQUE,
    email               VARCHAR(255) NOT NULL UNIQUE,
    first_name          VARCHAR(255),
    last_name           VARCHAR(255),
    role                VARCHAR(255) NOT NULL,
    current_address_id  BIGINT,
    default_card_id     BIGINT,
    created_at          TIMESTAMP NOT NULL
);

CREATE TABLE IF NOT EXISTS addresses (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         VARCHAR(255) NOT NULL REFERENCES users(id),
    label           VARCHAR(255),
    phone           VARCHAR(255) NOT NULL,
    identity_number VARCHAR(255) NOT NULL,
    address_line    VARCHAR(255) NOT NULL,
    city            VARCHAR(255) NOT NULL,
    country         VARCHAR(255) NOT NULL,
    zip_code        VARCHAR(255) NOT NULL,
    created_at      TIMESTAMP
);

ALTER TABLE users
    ADD CONSTRAINT fk_users_current_address
    FOREIGN KEY (current_address_id) REFERENCES addresses(id)
    DEFERRABLE INITIALLY DEFERRED;

ON CONFLICT (id) DO NOTHING;

WITH inserted AS (
    ON CONFLICT DO NOTHING
    RETURNING id, user_id
)
UPDATE users u
SET current_address_id = ins.id
FROM inserted ins
WHERE u.id = ins.user_id;
